<script lang="ts">
 import { components, emptyStack, scenarios, simulate, costOf, type ComponentId, type Result } from '$lib/game';
 import { onMount, tick } from 'svelte';
 let missionHeading: HTMLHeadingElement;
 let stack=$state(emptyStack());
 let round=$state(0); let credits=$state(scenarios[0].budget); let results=$state<Result[]>([]);
 let report=$state<Result|null>(null); let finished=$state(false); let best=$state(0); let help=$state(false);
 const scenario=$derived(scenarios[round]); const forecast=$derived(simulate(stack,scenario));
 const totalScore=$derived(results.reduce((sum,r)=>sum+r.score,0));
 onMount(()=>{try{best=Number(localStorage.getItem('architecture-lab-best')||0);}catch{/* Storage is optional. */}});
 function add(id:ComponentId){const c=components.find(c=>c.id===id)!;if(report||finished||credits<c.cost||stack[id]>=c.max)return;stack={...stack,[id]:stack[id]+1};credits-=c.cost;}
 function remove(id:ComponentId){const c=components.find(c=>c.id===id)!;if(report||finished||!stack[id])return;stack={...stack,[id]:stack[id]-1};credits+=c.cost;}
 function deploy(){if(report||finished)return;report=simulate(stack,scenario);results=[...results,report];if(round===scenarios.length-1){finished=true;if(totalScore>best){best=totalScore;try{localStorage.setItem('architecture-lab-best',String(best));}catch{/* Storage is optional. */}}}}
 async function next(){if(!report||finished)return;round++;credits+=scenarios[round].budget;report=null;await tick();missionHeading?.focus();}
 function restart(){stack=emptyStack();round=0;credits=scenarios[0].budget;results=[];report=null;finished=false;}
</script>

<svelte:head><title>Architecture Lab — Build. Scale. Survive.</title><meta name="description" content="A hands-on architecture strategy game. Build a system, survive production incidents, and learn the trade-offs behind resilient software."/><meta name="theme-color" content="#11191b"/></svelte:head>

<div class="shell">
 <header><a href="./" class="brand" aria-label="Architecture Lab home"><span class="brandmark">a<span>↗</span></span><span>architecture<span class="brand-light">lab</span></span></a><div class="header-right"><span class="lab-tag"><i></i> SYSTEM DESIGN SANDBOX</span><button class="text-button" onclick={()=>help=!help}>How to play <span>↗</span></button></div></header>
 {#if help}<section class="help"><div><h2>Your six-round architecture challenge</h2><p>Add components, inspect the forecast, then deploy. Each round brings a new workload and more budget. Your stack and unspent credits carry forward. Remove components for a full refund before deployment. Aim to serve 98% of traffic, reach 90 resilience, and stay below 300 ms.</p><p>This is an educational simulation: credits, latency, capacity, and failure models are simplified, not cloud pricing or real-world benchmarks. Only your best score is saved on this device.</p></div><button class="text-button" onclick={()=>help=false}>Close ×</button></section>{/if}
 <main>
 <section class="intro"><div><div class="eyebrow">BUILD. SCALE. SURVIVE.</div><h1>Good architecture<br/>is a series of <em>trade-offs.</em></h1><p>Six production challenges. One evolving system.<br class="desktop-break"/> Can you keep it running when everything changes?</p></div><div class="best"><span>PERSONAL BEST</span><strong>{best}<small> / 600</small></strong><span>Make every decision count.</span></div></section>
 <div class="workspace-head"><div class="workspace-title"><span class="pulse"></span> YOUR WORKSPACE <span class="muted">/ run {round+1 < 10 ? '0' : ''}{round+1}</span></div><button class="text-button" onclick={restart}>↻ Restart run</button></div>
 <div class="layout">
  <aside class="mission panel"><div class="section-label">MISSION BRIEF <span>{String(round+1).padStart(2,'0')} / 06</span></div><div class="steps" aria-label={`Round ${round+1} of 6`}>{#each scenarios as _,i}<span class:current={i===round} class:complete={i<round}>{i<round?'✓':i+1}</span>{/each}</div><div class="eyebrow muted">SCENARIO {String(round+1).padStart(2,'0')}</div><h2 bind:this={missionHeading} tabindex="-1">{scenario.name}</h2><p class="subtitle">{scenario.subtitle}</p><p class="brief">{scenario.brief}</p><div class="incident"><span>↯</span><div><small>PRODUCTION EVENT</small><strong>{scenario.incidentLabel}</strong></div></div><div class="workload"><div><span>Incoming traffic</span><strong>{forecast.incoming.toLocaleString()}<small> req/s</small></strong></div><div><span>Read / write mix</span><strong>{Math.round(scenario.reads*100)} / {Math.round((1-scenario.reads)*100)}<small> %</small></strong></div><div><span>Static assets</span><strong>{Math.round(scenario.assets*100)}<small> % of traffic</small></strong></div></div><div class="budget"><span>AVAILABLE BUDGET</span><strong><span>◈</span> {credits}<small> credits</small></strong><p>+{scenario.budget} this round · unspent credits carry over</p></div></aside>
  <section class="canvas panel"><div class="section-label">LIVE ARCHITECTURE <span class="tiny-pill">{Object.values(stack).reduce((a,b)=>a+b,0)+2} nodes</span></div><div class="diagram"><div class="traffic-label"><span>◎</span> {forecast.incoming.toLocaleString()} requests / second</div><div class="line"></div><div class="node edge" class:enabled={stack.cdn>0}><span>◇</span><div><strong>{stack.cdn?'Edge network':'Internet gateway'}</strong><small>{stack.cdn?'Static assets served at the edge':'Traffic enters your system'}</small></div><b>{stack.cdn?'ON':'→'}</b></div><div class="line"></div><div class="node app"><span>▤</span><div><strong>Application tier</strong><small>{1+stack.replica} instance{stack.replica?'s':''} · {forecast.compute.toLocaleString()} req/s available</small></div><b>×{stack.replica+1}</b></div><div class="branches"><div class="mini-node" class:enabled={stack.cache>0}><span>⚡</span><strong>Cache</strong><small>{stack.cache ? `×${stack.cache} active` : 'Not installed'}</small></div><div class="mini-node" class:enabled={stack.queue>0}><span>⇥</span><strong>Queue</strong><small>{stack.queue ? `×${stack.queue} active` : 'Not installed'}</small></div></div><div class="line short"></div><div class="node data"><span>◉</span><div><strong>Data tier</strong><small>Primary + {stack.database} replica{stack.database===1?'':'s'} · {forecast.database.toLocaleString()} ops/s</small></div><b>×{stack.database+1}</b></div><div class="monitor" class:enabled={stack.observability>0}>⌁ {stack.observability?'Observability online · recovery boost active':'Observability offline'}</div></div><div class="canvas-foot"><span><i></i> Forecast updates as you build</span><span>Stack value <strong>{costOf(stack)} ◈</strong></span></div></section>
  <aside class="metrics panel"><div class="section-label">DEPLOYMENT FORECAST</div><div class="metric"><span>Traffic served</span><strong class:good={forecast.served>=98}>{forecast.served}<small>%</small></strong><div class="meter"><span style={`width:${forecast.served}%`} class:good={forecast.served>=98}></span></div><small>Target ≥ 98%</small></div><div class="metric"><span>Resilience</span><strong class:good={forecast.reliability>=90}>{forecast.reliability}<small>/100</small></strong><div class="meter"><span style={`width:${forecast.reliability}%`} class:good={forecast.reliability>=90}></span></div><small>Target ≥ 90</small></div><div class="latency"><span>Response time</span><strong class:good={forecast.latency<300}>{forecast.latency}<small> ms</small></strong><small>Target &lt; 300 ms</small></div><div class="bottleneck"><small>LIMITING FACTOR</small><strong>{forecast.bottleneck}</strong></div><div class="score"><span>RUN SCORE</span><strong>{totalScore}<small> / 600</small></strong></div></aside>
 </div>
 <section class="components"><div class="component-heading"><div><h2>Your building blocks</h2><p>A stronger system starts with the right next decision.</p></div><span class="muted">Add to install · − to refund</span></div><div class="cards">{#each components as c}<article class="component-card" class:installed={stack[c.id]>0}><div class="card-top"><span class="component-icon">{c.icon}</span><span class="count">{stack[c.id]} / {c.max}</span></div><h3>{c.name}</h3><p>{c.description}</p><details><summary>Why it matters</summary><p>{c.lesson}</p></details><div class="card-actions"><strong>{c.cost} <span>◈</span></strong><div><button class="remove" disabled={!stack[c.id]||!!report||finished} onclick={()=>remove(c.id)} aria-label={`Remove ${c.name}`}>−</button><button class="add" disabled={credits<c.cost||stack[c.id]>=c.max||!!report||finished} onclick={()=>add(c.id)} aria-label={`Add ${c.name}`}>+ Add</button></div></div></article>{/each}</div></section>
 <section class="deploy-bar" aria-live="polite">{#if report}<div><span class="eyebrow">{finished?'RUN COMPLETE':report.passed?'DEPLOYMENT HEALTHY':'LESSONS FROM PRODUCTION'}</span><h2>{finished?`${totalScore} / 600 — ${totalScore>=550?'Principal architect':totalScore>=420?'Systems thinker':'Keep experimenting'}`:report.passed?'Your system held up.':`${report.bottleneck==='No bottleneck'?'Resilience needs attention':report.bottleneck+' needs attention'}.`}</h2><p>{finished?'Try another run and explore a different architecture.':`${report.score}/100 this round. ${report.passed?'Take your architecture into the next challenge.':'Keep learning: your system and remaining credits carry forward.'}`}</p></div><button class="deploy" onclick={finished?restart:next}>{finished?'Play again':'Next challenge'} <span>→</span></button>{:else}<div><span class="eyebrow">READY WHEN YOU ARE</span><h2>Put your architecture to the test.</h2><p>Deploy locks in this round. Your next challenge is waiting.</p></div><button class="deploy" onclick={deploy}>Deploy system <span>↗</span></button>{/if}</section>
 {#if results.length}<section class="history"><span class="eyebrow">DEPLOYMENT HISTORY</span><div>{#each results as result,i}<span class:success={result.passed}>{String(i+1).padStart(2,'0')} · {scenarios[i].name} <strong>{result.score}/100</strong></span>{/each}</div></section>{/if}
 </main><footer><span class="brand-light">architecture lab</span><span>A little practice for your next big system.</span><span>SvelteKit · Built for curious engineers</span></footer>
</div>

